**`useTelegramWebApp.ts`**
```ts
import { useEffect, useState } from "react";
import type { TelegramWebApp } from "./telegram-webapp";

export function useTelegramWebApp(): TelegramWebApp | undefined {
  const [webApp, setWebApp] = useState<TelegramWebApp | undefined>(
    () => window.Telegram?.WebApp
  );

  useEffect(() => {
    const app = window.Telegram?.WebApp;
    if (!app) return;
    app.ready();
    setWebApp(app);
  }, []);

  return webApp;
}
```

**`CheckoutScreen.tsx`**
```tsx
import { useCallback, useEffect, useMemo, useState } from "react";
import type { ChangeEvent } from "react";
import type { CartItem, DeliveryAddress, DeliveryAddressErrors } from "./types";
import { useTelegramWebApp } from "./useTelegramWebApp";
import "./CheckoutScreen.css";

const DELIVERY_FEE_CENTS = 500;

const EMPTY_ADDRESS: DeliveryAddress = {
  fullName: "",
  phone: "",
  city: "",
  street: "",
  apartment: "",
  postalCode: "",
  comment: "",
};

function formatPrice(cents: number, currency: string): string {
  return new Intl.NumberFormat(undefined, { style: "currency", currency }).format(cents / 100);
}

function validateAddress(address: DeliveryAddress): DeliveryAddressErrors {
  const errors: DeliveryAddressErrors = {};
  if (!address.fullName.trim()) errors.fullName = "Enter your full name";
  if (!/^\+?[0-9\s()-]{7,}$/.test(address.phone.trim())) {
    errors.phone = "Enter a valid phone number";
  }
  if (!address.city.trim()) errors.city = "Enter your city";
  if (!address.street.trim()) errors.street = "Enter your street and house number";
  if (!address.postalCode.trim()) errors.postalCode = "Enter a postal code";
  return errors;
}

export interface CheckoutScreenProps {
  items: CartItem[];
  initialAddress?: Partial<DeliveryAddress>;
  onBack: () => void;
  onPay: (address: DeliveryAddress, items: CartItem[]) => Promise<void> | void;
}

export function CheckoutScreen({ items, initialAddress, onBack, onPay }: CheckoutScreenProps) {
  const webApp = useTelegramWebApp();
  const [address, setAddress] = useState<DeliveryAddress>({ ...EMPTY_ADDRESS, ...initialAddress });
  const [touched, setTouched] = useState<Partial<Record<keyof DeliveryAddress, boolean>>>({});
  const [submitting, setSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState<string | null>(null);

  const currency = items[0]?.currency ?? "USD";
  const subtotalCents = useMemo(
    () => items.reduce((sum, item) => sum + item.unitPriceCents * item.quantity, 0),
    [items]
  );
  const totalCents = subtotalCents + (items.length > 0 ? DELIVERY_FEE_CENTS : 0);

  const errors = useMemo(() => validateAddress(address), [address]);
  const isFormValid = Object.keys(errors).length === 0 && items.length > 0;
  const isDirty = useMemo(
    () => Object.values(address).some((value) => value.trim().length > 0),
    [address]
  );

  const handleFieldChange = useCallback(
    (field: keyof DeliveryAddress) => (e: ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
      setAddress((prev) => ({ ...prev, [field]: e.target.value }));
    },
    []
  );

  const handleFieldBlur = useCallback(
    (field: keyof DeliveryAddress) => () => {
      setTouched((prev) => ({ ...prev, [field]: true }));
    },
    []
  );

  const submit = useCallback(async () => {
    if (!isFormValid || submitting) return;
    setSubmitting(true);
    setSubmitError(null);
    webApp?.HapticFeedback.impactOccurred("medium");
    webApp?.MainButton.showProgress(true);
    try {
      await onPay(address, items);
      webApp?.HapticFeedback.notificationOccurred("success");
    } catch (err) {
      webApp?.HapticFeedback.notificationOccurred("error");
      const message = err instanceof Error ? err.message : "Payment failed. Please try again.";
      setSubmitError(message);
      webApp?.showAlert(message);
    } finally {
      setSubmitting(false);
      webApp?.MainButton.hideProgress();
    }
  }, [isFormValid, submitting, address, items, onPay, webApp]);

  // Telegram owns back navigation; the page only supplies the handler, never a second arrow.
  useEffect(() => {
    if (!webApp) return;
    webApp.BackButton.show();
    webApp.BackButton.onClick(onBack);
    return () => {
      webApp.BackButton.offClick(onBack);
      webApp.BackButton.hide();
    };
  }, [webApp, onBack]);

  // The screen's one primary action lives in the host's bottom bar button, not a page footer.
  useEffect(() => {
    if (!webApp) return;
    webApp.MainButton.setText(`Pay ${formatPrice(totalCents, currency)}`);
    webApp.MainButton.onClick(submit);
    webApp.MainButton.show();
    if (isFormValid && !submitting) {
      webApp.MainButton.enable();
    } else {
      webApp.MainButton.disable();
    }
    return () => {
      webApp.MainButton.offClick(submit);
    };
  }, [webApp, submit, isFormValid, submitting, totalCents, currency]);

  useEffect(() => {
    if (!webApp) return;
    if (isDirty) {
      webApp.enableClosingConfirmation();
    } else {
      webApp.disableClosingConfirmation();
    }
    return () => webApp.disableClosingConfirmation();
  }, [webApp, isDirty]);

  useEffect(() => {
    webApp?.expand();
  }, [webApp]);

  const fieldError = (field: keyof DeliveryAddress) => (touched[field] ? errors[field] : undefined);

  return (
    <div className="checkout-screen">
      <div className="checkout-screen__content">
        {!webApp && (
          <button type="button" className="checkout-screen__fallback-back" onClick={onBack}>
            ‹ Back to cart
          </button>
        )}

        <section aria-labelledby="checkout-items-heading" className="checkout-section">
          <h2 id="checkout-items-heading" className="checkout-section__title">
            Your order
          </h2>
          <ul className="cart-list">
            {items.map((item) => (
              <li key={item.id} className="cart-list__item">
                {item.imageUrl ? (
                  <img src={item.imageUrl} alt="" className="cart-list__thumb" />
                ) : (
                  <div className="cart-list__thumb cart-list__thumb--placeholder" aria-hidden="true" />
                )}
                <div className="cart-list__info">
                  <span className="cart-list__title">{item.title}</span>
                  <span className="cart-list__qty">Qty {item.quantity}</span>
                </div>
                <span className="cart-list__price">
                  {formatPrice(item.unitPriceCents * item.quantity, item.currency)}
                </span>
              </li>
            ))}
          </ul>

          {items.length === 0 ? (
            <p className="checkout-screen__empty">Your cart is empty.</p>
          ) : (
            <dl className="order-summary">
              <div className="order-summary__row">
                <dt>Subtotal</dt>
                <dd>{formatPrice(subtotalCents, currency)}</dd>
              </div>
              <div className="order-summary__row">
                <dt>Delivery</dt>
                <dd>{formatPrice(DELIVERY_FEE_CENTS, currency)}</dd>
              </div>
              <div className="order-summary__row order-summary__row--total">
                <dt>Total</dt>
                <dd>{formatPrice(totalCents, currency)}</dd>
              </div>
            </dl>
          )}
        </section>

        <section aria-labelledby="checkout-address-heading" className="checkout-section">
          <h2 id="checkout-address-heading" className="checkout-section__title">
            Delivery address
          </h2>
          <form className="address-form" onSubmit={(e) => e.preventDefault()}>
            <label className="address-form__field">
              <span>Full name</span>
              <input
                type="text"
                name="fullName"
                autoComplete="name"
                value={address.fullName}
                onChange={handleFieldChange("fullName")}
                onBlur={handleFieldBlur("fullName")}
              />
              {fieldError("fullName") && <small className="address-form__error">{fieldError("fullName")}</small>}
            </label>

            <label className="address-form__field">
              <span>Phone number</span>
              <input
                type="tel"
                name="phone"
                autoComplete="tel"
                value={address.phone}
                onChange={handleFieldChange("phone")}
                onBlur={handleFieldBlur("phone")}
              />
              {fieldError("phone") && <small className="address-form__error">{fieldError("phone")}</small>}
            </label>

            <label className="address-form__field">
              <span>City</span>
              <input
                type="text"
                name="city"
                autoComplete="address-level2"
                value={address.city}
                onChange={handleFieldChange("city")}
                onBlur={handleFieldBlur("city")}
              />
              {fieldError("city") && <small className="address-form__error">{fieldError("city")}</small>}
            </label>

            <label className="address-form__field">
              <span>Street and house number</span>
              <input
                type="text"
                name="street"
                autoComplete="address-line1"
                value={address.street}
                onChange={handleFieldChange("street")}
                onBlur={handleFieldBlur("street")}
              />
              {fieldError("street") && <small className="address-form__error">{fieldError("street")}</small>}
            </label>

            <label className="address-form__field">
              <span>Apartment / unit (optional)</span>
              <input
                type="text"
                name="apartment"
                autoComplete="address-line2"
                value={address.apartment}
                onChange={handleFieldChange("apartment")}
                onBlur={handleFieldBlur("apartment")}
              />
            </label>

            <label className="address-form__field">
              <span>Postal code</span>
              <input
                type="text"
                name="postalCode"
                autoComplete="postal-code"
                value={address.postalCode}
                onChange={handleFieldChange("postalCode")}
                onBlur={handleFieldBlur("postalCode")}
              />
              {fieldError("postalCode") && (
                <small className="address-form__error">{fieldError("postalCode")}</small>
              )}
            </label>

            <label className="address-form__field">
              <span>Delivery notes (optional)</span>
              <textarea
                name="comment"
                rows={3}
                value={address.comment}
                onChange={handleFieldChange("comment")}
                onBlur={handleFieldBlur("comment")}
              />
            </label>
          </form>
        </section>

        {submitError && (
          <p className="checkout-screen__submit-error" role="alert">
            {submitError}
          </p>
        )}

        {!webApp && (
          <button
            type="button"
            className="checkout-screen__fallback-pay"
            disabled={!isFormValid || submitting}
            onClick={submit}
          >
            {submitting ? "Processing…" : `Pay ${formatPrice(totalCents, currency)}`}
          </button>
        )}
      </div>
    </div>
  );
}
```

